// Cache Price_Log (last 7 days) in workflow static data.
// Avoids N repeated Google Sheets reads inside the keyword/product loops.
const today = new Date();
const sevenDaysAgo = new Date(today.getTime() - 7 * 24 * 60 * 60 * 1000);

const allItems = $input.all();
const staticData = $getWorkflowStaticData('global');

staticData.pricelog_cache = allItems
  .map(i => i.json)
  .filter(row => {
    if (!row.Date) return false;
    try { return new Date(row.Date) >= sevenDaysAgo; }
    catch { return false; }
  });

staticData.pricelog_loaded_at = new Date().toISOString();
staticData.today = today.toISOString().split('T')[0];

// Output exactly ONE item so Read Tracked_Keywords runs once (not N times)
return [{ json: { status: 'cache_ready', cached_rows: staticData.pricelog_cache.length } }];

// Combine Talabat + Breadfast responses into flat products array.
// $json = Breadfast API response (current input)
// $('HTTP_Talabat').first().json = Talabat API response
// $('Loop_Keywords').item.json = current keyword row from Google Sheets

const keyword = $('Loop_Keywords').item.json;
const talabatRaw = $('HTTP_Talabat').first()?.json || {};
const breadfastRaw = $json || {};
const today = new Date().toISOString().split('T')[0];

const products = [];

// ─────────────────────────────────────────────────────
// PARSE TALABAT RESPONSE
// Adjust the path below after inspecting DevTools response.
// Common paths: .data.items | .results | .products | .data.products
// ─────────────────────────────────────────────────────
const talabatItems =
  talabatRaw?.data?.items ??
  talabatRaw?.results ??
  talabatRaw?.products ??
  talabatRaw?.data?.products ??
  [];

if (Array.isArray(talabatItems)) {
  for (const item of talabatItems) {
    products.push({
      platform: 'Talabat',
      keyword: keyword.Keyword,
      our_sku: keyword.Our_SKU,
      brand_context: keyword.Brand,
      category: keyword.Category,
      is_ours_context: String(keyword.Is_Ours).toLowerCase() === 'true',
      rawText: JSON.stringify(item).substring(0, 2000), // cap at 2000 chars for Groq
      scrape_date: today
    });
  }
}

// ─────────────────────────────────────────────────────
// PARSE BREADFAST RESPONSE
// Common paths: .data | .products | .items | .data.products
// ─────────────────────────────────────────────────────
const breadfastItems =
  breadfastRaw?.data ??
  breadfastRaw?.products ??
  breadfastRaw?.items ??
  breadfastRaw?.data?.products ??
  [];

if (Array.isArray(breadfastItems)) {
  for (const item of breadfastItems) {
    products.push({
      platform: 'Breadfast',
      keyword: keyword.Keyword,
      our_sku: keyword.Our_SKU,
      brand_context: keyword.Brand,
      category: keyword.Category,
      is_ours_context: String(keyword.Is_Ours).toLowerCase() === 'true',
      rawText: JSON.stringify(item).substring(0, 2000),
      scrape_date: today
    });
  }
}

// If no products found on either platform, return sentinel item
if (products.length === 0) {
  return [{
    json: {
      _no_results: true,
      platform: 'BOTH',
      keyword: keyword.Keyword,
      scrape_date: today
    }
  }];
}

// Add random delay between 1-3s to reduce anti-bot risk
const delay = ms => new Promise(r => setTimeout(r, ms));
await delay(1000 + Math.random() * 2000);

return products.map(p => ({ json: p }));

// Extract the JSON from Groq AI Agent output.
// AI Agent returns output in $json.output field.

const aiOutput = $json.output || $json.text || '';

// Pass through sentinel no-results items
if ($json._no_results) {
  return [{ json: { ...$json, _skip: true } }];
}

let normalized;
try {
  // Strip markdown code fences if AI added them
  const cleaned = aiOutput
    .replace(/```json\n?/gi, '')
    .replace(/```\n?/g, '')
    .trim();
  const jsonMatch = cleaned.match(/\{[\s\S]*\}/);
  normalized = jsonMatch ? JSON.parse(jsonMatch[0]) : JSON.parse(cleaned);
} catch (e) {
  // Fallback: preserve what we know, flag parse error
  normalized = {
    brand: $json.brand_context || 'Unknown',
    product_name: $json.keyword || 'Unknown',
    pack_size: null,
    price_egp: 0,
    original_price_egp: null,
    promo_type: 'None',
    discount_percent: null,
    in_stock: false,
    stock_hint: 'AI_PARSE_ERROR: ' + e.message.substring(0, 100),
    platform: $json.platform,
    _parse_error: true
  };
}

return [{
  json: {
    ...normalized,
    // Enrich with keyword context
    our_sku:    $json.our_sku    || '',
    category:   $json.category   || '',
    is_ours:    $json.is_ours_context === true || String($json.is_ours_context) === 'true',
    platform:   $json.platform   || normalized.platform || '',
    keyword:    $json.keyword    || '',
    scrape_date: $json.scrape_date || new Date().toISOString().split('T')[0],
    _skip:      false
  }
}];

// OOS Detection — spec Section 6.2
// Uses pricelog_cache stored by Code_CachePriceLog at workflow start.

const curr = $json;
const today = new Date().toISOString().split('T')[0];

// Skip items flagged as no-results or parse errors
if (curr._skip) {
  return [{ json: { ...curr, alertType: null, _skipped: true } }];
}

const staticData = $getWorkflowStaticData('global');
const cache = staticData.pricelog_cache || [];

// Find the most recent previous entry for this product on the same platform
const prevEntry = cache
  .filter(e => {
    const platformMatch = e.Platform === curr.platform;
    const skuMatch =
      (e.Matched_SKU && e.Matched_SKU === curr.our_sku) ||
      (e.Raw_Product_Name && curr.product_name &&
        e.Raw_Product_Name.toLowerCase().includes(curr.product_name.toLowerCase().substring(0, 12)));
    const notToday = e.Date !== today;
    return platformMatch && skuMatch && notToday;
  })
  .sort((a, b) => new Date(b.Date) - new Date(a.Date))[0];

let alertType = null;
let first_seen_oos = '';

if (prevEntry) {
  const wasInStock =
    prevEntry.In_Stock === 'TRUE' ||
    prevEntry.In_Stock === true ||
    prevEntry.In_Stock === 'true';

  if (wasInStock && !curr.in_stock) {
    // Transition: in-stock → out-of-stock
    alertType = curr.is_ours
      ? 'WARNING_OOS_START'
      : 'OPPORTUNITY_COMPETITOR_OOS';
    first_seen_oos = new Date().toISOString();
  } else if (!curr.in_stock && curr.is_ours) {
    // Already OOS — check if >48 hours
    const fso = prevEntry.First_Seen_OOS || '';
    if (fso) {
      const hours = (Date.now() - new Date(fso)) / 36e5;
      if (hours > 48) {
        alertType = 'CRITICAL_OOS_PERSISTENT';
      }
      first_seen_oos = fso; // preserve original OOS timestamp
    }
  }
} else if (!curr.in_stock && curr.is_ours) {
  // No previous entry found, product is OOS — treat as new OOS event
  alertType = 'WARNING_OOS_START';
  first_seen_oos = new Date().toISOString();
}

// Also update cache with today's entry so within-day deduplication works
if (staticData.pricelog_cache) {
  staticData.pricelog_cache.push({
    Date: today,
    Platform: curr.platform,
    Matched_SKU: curr.our_sku,
    Raw_Product_Name: curr.product_name,
    In_Stock: curr.in_stock,
    First_Seen_OOS: first_seen_oos,
    Price_EGP: curr.price_egp
  });
}

return [{
  json: {
    // Price_Log columns (mapped to exact sheet headers)
    Date:                today,
    Platform:            curr.platform,
    Raw_Product_Name:    curr.product_name || '',
    Matched_SKU:         curr.our_sku || '',
    Brand:               curr.brand || curr.brand_context || '',
    Category:            curr.category || '',
    Is_Ours:             curr.is_ours,
    Price_EGP:           curr.price_egp || 0,
    Original_Price_EGP:  curr.original_price_egp || '',
    Promo_Type:          curr.promo_type || 'None',
    Discount_Percent:    curr.discount_percent || '',
    In_Stock:            curr.in_stock,
    Stock_Hint:          curr.stock_hint || '',
    First_Seen_OOS:      first_seen_oos,
    // Pass-through for downstream nodes
    alertType:           alertType,
    _is_ours:            curr.is_ours,
    _price_egp:          curr.price_egp || 0,
    _skipped:            false
  }
}];

// Price Index Calculation — spec Section 6.3
// For competitor products: Index_Percent = (Competitor_Price / Our_Price) * 100
// Looks up Corona's price for the same category from today's cached data.

const curr = $json;

// Skip errors / no-result items
if (curr._skipped || !curr.Price_EGP || curr.Price_EGP === 0) {
  return [{ json: curr }];
}

// Only calculate index for competitor products
if (curr._is_ours === true || curr.Is_Ours === true) {
  return [{ json: { ...curr, _price_index_row: null } }];
}

const staticData = $getWorkflowStaticData('global');
const cache = staticData.pricelog_cache || [];
const today = curr.Date;

// Find Corona's price for same category + platform (today)
const coronaRef = cache
  .filter(e =>
    (e.Is_Ours === true || e.Is_Ours === 'TRUE' || e.Is_Ours === 'true') &&
    e.Category === curr.Category &&
    e.Platform === curr.Platform &&
    e.In_Stock !== false && e.In_Stock !== 'FALSE' && e.In_Stock !== 'false'
  )
  .sort((a, b) => new Date(b.Date) - new Date(a.Date))[0];

if (!coronaRef || !coronaRef.Price_EGP) {
  // No Corona reference price found for this category+platform today
  return [{ json: { ...curr, _price_index_row: null } }];
}

const indexPercent = Math.round((curr.Price_EGP / coronaRef.Price_EGP) * 100 * 10) / 10;

return [{
  json: {
    ...curr,
    _price_index_row: {
      Date:             today,
      SKU:              curr.Matched_SKU,
      Platform:         curr.Platform,
      Category:         curr.Category,
      Our_Price:        coronaRef.Price_EGP,
      Competitor_Price: curr.Price_EGP,
      Competitor_Brand: curr.Brand,
      Index_Percent:    indexPercent
    }
  }
}];

